-- Philippines: ES/DE/FR milestone translations, hand-translated from
-- the English rows in 332_philippines_milestones.sql. Proper nouns,
-- regulation numbers, and institution names (RR, BIR, TRAIN Law,
-- LT100, EIS, ESRS, PHP) stay untranslated, matching the convention
-- used for DIAN/CUFE/RADIAN in the Colombia migrations.

-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-train-law-2018', 'es', 'La ley TRAIN modifica el NIRC (RA 10963)', 'La Ley de Reforma Tributaria para la Aceleración y la Inclusión (TRAIN Law) modificó las Secciones 237 y 237-A del Código Nacional de Rentas Internas, autorizando a la Oficina de Rentas Internas (BIR) a exigir facturas/recibos electrónicos y reporte electrónico de ventas casi en tiempo real a grandes contribuyentes y exportadores. Esto estableció la base legal para todo lo que vino después, pero no creó por sí sola ninguna obligación de facturación vigente -- la BIR aún debía redactar el reglamento y construir el sistema.', '["Todavía no se requiere ninguna acción -- esta es la ley habilitante, no un mandato operativo.", "Los grandes contribuyentes y exportadores deben tener en cuenta que fueron señalados desde el inicio como la población objetivo eventual."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-lt100-pilot-2022', 'es', 'La RR 8-2022 lanza el piloto LT100', 'El Reglamento de Rentas Nº 8-2022 (RR 8-2022) emitió las primeras reglas de implementación de las disposiciones de facturación electrónica de la ley TRAIN, y la BIR lanzó un piloto voluntario con 100 grandes contribuyentes seleccionados ("LT100") en el Sistema de Facturación/Recibos Electrónicos (EIS) a partir del 1 de julio de 2022. Problemas técnicos y de capacidad obligaron a la BIR a pausar el programa más adelante ese año, y permaneció estancado durante aproximadamente dos años antes de reanudarse formalmente bajo la RR 11-2025.', '["La participación en el piloto era solo por selección de la BIR -- no existía ninguna obligación general durante esta fase.", "Las empresas fuera del piloto no tenían nada que hacer todavía."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-mandate-resumed-2025', 'es', 'La RR 11-2025 reanuda y amplía formalmente el mandato', 'Tras la ley CREATE MORE, el Reglamento de Rentas Nº 11-2025 (RR 11-2025) reanudó formalmente el programa de facturación electrónica estancado y fijó la lista de contribuyentes obligados que sigue vigente hoy: Grandes Contribuyentes, negocios de comercio electrónico/digitales de cualquier tamaño, exportadores, usuarios de Sistemas de Contabilidad Computarizados o sistemas POS con capacidad de facturación electrónica, y Empresas Registradas con incentivos fiscales. Otorgó a los contribuyentes obligados un año para cumplir -- un plazo del 14 de marzo de 2026 que fue superado antes de llegar (véase la RR 26-2025).', '["Confirme si su empresa entra en alguna de las categorías recién incluidas -- la lista es más amplia que solo \"grandes contribuyentes\".", "Las microempresas (ventas brutas anuales inferiores a PHP 3 millones) siguen exentas, pero pueden optar voluntariamente por incentivos de deducción de costos."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-phase1-deadline-2026', 'es', 'La RR 26-2025 extiende la Fase 1 hasta el 31 de diciembre de 2026', 'El Reglamento de Rentas Nº 26-2025 (RR 26-2025) postergó el plazo de cumplimiento de la Fase 1 del 14 de marzo de 2026 al 31 de diciembre de 2026 -- unos nueve meses y medio adicionales para los contribuyentes designados bajo la RR 11-2025. Fuentes del sector describen el efecto práctico como que la facturación electrónica se vuelve obligatoria a partir del 1 de enero de 2027. Esta es la segunda vez que este plazo específico se mueve (el propio mandato también estuvo pausado unos dos años tras su piloto de 2022), así que trate la fecha como el objetivo oficial actual y no como una certeza definitiva.', '["Contribuyentes obligados: tengan listas facturas electrónicas estructuradas y legibles por máquina (no PDF) para emitir antes del plazo.", "Confirme que su software de facturación/POS/CAS puede generar el formato de datos estructurado requerido.", "Esté atento a nuevas guías de la BIR -- el plazo ya se movió una vez y la plataforma de transmisión (ESRS) todavía se está construyendo."]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-train-law-2018', 'de', 'Das TRAIN-Gesetz ändert den NIRC (RA 10963)', 'Das Gesetz zur Steuerreform für Beschleunigung und Inklusion (TRAIN-Gesetz) änderte die Abschnitte 237 und 237-A des National Internal Revenue Code und ermächtigte die Steuerbehörde BIR, von Großsteuerpflichtigen und Exporteuren elektronische Rechnungen/Belege sowie eine nahezu in Echtzeit erfolgende elektronische Umsatzmeldung zu verlangen. Damit wurde die rechtliche Grundlage für alles Folgende geschaffen, jedoch entstand daraus allein noch keine geltende Rechnungsstellungspflicht -- die BIR musste erst noch Durchführungsvorschriften erlassen und das System aufbauen.', '["Noch keine Maßnahme erforderlich -- dies ist das ermächtigende Gesetz, nicht ein operatives Mandat.", "Großsteuerpflichtige und Exporteure sollten beachten, dass sie von Anfang an als spätere Zielgruppe genannt wurden."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-lt100-pilot-2022', 'de', 'RR 8-2022 startet das LT100-Pilotprogramm', 'Die Revenue Regulations Nr. 8-2022 (RR 8-2022) erließ die ersten Durchführungsvorschriften zu den E-Invoicing-Bestimmungen des TRAIN-Gesetzes, und die BIR startete ab dem 1. Juli 2022 ein freiwilliges Pilotprogramm mit 100 ausgewählten Großsteuerpflichtigen ("LT100") im Electronic Invoicing/Receipting System (EIS). Technische Probleme und Kapazitätsengpässe zwangen die BIR, das Programm noch im selben Jahr zu pausieren; es blieb rund zwei Jahre lang ausgesetzt, bevor es unter RR 11-2025 formell wieder aufgenommen wurde.', '["Die Teilnahme am Pilotprogramm erfolgte ausschließlich durch Auswahl der BIR -- in dieser Phase bestand keine allgemeine Pflicht.", "Unternehmen außerhalb des Pilotprogramms mussten vorerst nichts unternehmen."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-mandate-resumed-2025', 'de', 'RR 11-2025 nimmt das Mandat formell wieder auf und erweitert es', 'Im Zuge des CREATE-MORE-Gesetzes nahm die Revenue Regulations Nr. 11-2025 (RR 11-2025) das zuvor ausgesetzte E-Invoicing-Programm formell wieder auf und legte die auch heute noch geltende Liste erfasster Steuerpflichtiger fest: Großsteuerpflichtige, E-Commerce-/Digitalunternehmen jeder Größe, Exporteure, Nutzer computergestützter Buchhaltungssysteme oder POS-Systeme mit E-Invoicing-Funktion sowie registrierte Unternehmen mit Steueranreizen. Den erfassten Steuerpflichtigen wurde ein Jahr zur Umstellung eingeräumt -- eine Frist zum 14. März 2026, die noch vor ihrem Eintritt durch RR 26-2025 ersetzt wurde.', '["Prüfen Sie, ob Ihr Unternehmen in eine der neu erfassten Kategorien fällt -- die Liste ist breiter als nur \"Großsteuerpflichtige\".", "Kleinstunternehmen (Jahresbruttoumsatz unter PHP 3 Millionen) bleiben befreit, können aber freiwillig teilnehmen, um von Kostenabzugsanreizen zu profitieren."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-phase1-deadline-2026', 'de', 'RR 26-2025 verlängert Phase 1 bis zum 31. Dezember 2026', 'Die Revenue Regulations Nr. 26-2025 (RR 26-2025) verschob die Frist für die Einhaltung von Phase 1 vom 14. März 2026 auf den 31. Dezember 2026 -- rund neuneinhalb Monate zusätzlicher Vorlauf für die unter RR 11-2025 benannten Steuerpflichtigen. Branchenquellen beschreiben die praktische Wirkung so, dass E-Invoicing ab dem 1. Januar 2027 verpflichtend wird. Dies ist bereits die zweite Verschiebung dieser konkreten Frist (auch das Mandat selbst war nach seinem Pilotprogramm 2022 rund zwei Jahre ausgesetzt) -- betrachten Sie das Datum daher als aktuelles offizielles Ziel und nicht als endgültige Gewissheit.', '["Erfasste Steuerpflichtige: strukturierte, maschinenlesbare E-Rechnungen (keine PDFs) bis zur Frist bereithalten.", "Prüfen, ob die eigene Rechnungs-/POS-/CAS-Software das erforderliche strukturierte Datenformat erzeugen kann.", "Weitere BIR-Vorgaben im Blick behalten -- die Frist hat sich bereits einmal verschoben, und die Übermittlungsplattform (ESRS) befindet sich noch im Aufbau."]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-train-law-2018', 'fr', 'La loi TRAIN modifie le NIRC (RA 10963)', 'La loi de réforme fiscale pour l''accélération et l''inclusion (loi TRAIN) a modifié les sections 237 et 237-A du Code national des impôts internes, autorisant le Bureau of Internal Revenue (BIR) à exiger des grands contribuables et des exportateurs des factures/reçus électroniques ainsi qu''un signalement électronique des ventes quasiment en temps réel. Cela a posé la base juridique de tout ce qui a suivi, mais n''a créé, à lui seul, aucune obligation de facturation effective -- le BIR devait encore rédiger les règles d''application et construire le système.', '["Aucune action requise pour l''instant -- il s''agit de la loi habilitante, pas d''un mandat opérationnel.", "Les grands contribuables et exportateurs doivent noter qu''ils ont été désignés dès le départ comme la population cible à terme."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-lt100-pilot-2022', 'fr', 'Le RR 8-2022 lance le programme pilote LT100', 'Le règlement fiscal n° 8-2022 (RR 8-2022) a publié les premières règles d''application des dispositions de facturation électronique de la loi TRAIN, et le BIR a lancé un programme pilote volontaire avec 100 grands contribuables sélectionnés ("LT100") sur le système de facturation/réception électronique (EIS) à partir du 1er juillet 2022. Des problèmes techniques et de capacité ont contraint le BIR à suspendre le programme plus tard dans l''année, et celui-ci est resté à l''arrêt pendant environ deux ans avant de reprendre formellement sous le RR 11-2025.', '["La participation au programme pilote se faisait uniquement sur sélection du BIR -- aucune obligation générale n''existait durant cette phase.", "Les entreprises hors du programme pilote n''avaient encore rien à faire."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-mandate-resumed-2025', 'fr', 'Le RR 11-2025 relance et élargit formellement le mandat', 'À la suite de la loi CREATE MORE, le règlement fiscal n° 11-2025 (RR 11-2025) a formellement relancé le programme de facturation électronique jusque-là suspendu et a fixé la liste des contribuables assujettis toujours en vigueur aujourd''hui : grands contribuables, entreprises de commerce électronique/numériques de toute taille, exportateurs, utilisateurs de systèmes comptables informatisés ou de systèmes de point de vente disposant d''une capacité de facturation électronique, ainsi que les entreprises enregistrées bénéficiant d''incitations fiscales. Il a accordé aux contribuables assujettis un an pour se conformer -- une échéance fixée au 14 mars 2026, elle-même remplacée avant son échéance par le RR 26-2025.', '["Vérifiez si votre entreprise entre dans l''une des catégories nouvellement couvertes -- la liste est plus large que les seuls \"grands contribuables\".", "Les microentreprises (chiffre d''affaires annuel brut inférieur à 3 millions de PHP) restent exemptées mais peuvent opter volontairement pour bénéficier des incitations de déduction de coûts."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ph-phase1-deadline-2026', 'fr', 'Le RR 26-2025 prolonge la Phase 1 jusqu''au 31 décembre 2026', 'Le règlement fiscal n° 26-2025 (RR 26-2025) a repoussé l''échéance de conformité de la Phase 1 du 14 mars 2026 au 31 décembre 2026 -- environ neuf mois et demi de délai supplémentaire pour les contribuables désignés par le RR 11-2025. Des sources du secteur décrivent l''effet pratique comme rendant la facturation électronique obligatoire à compter du 1er janvier 2027. C''est la deuxième fois que cette échéance précise est repoussée (le mandat lui-même avait aussi été suspendu environ deux ans après son programme pilote de 2022) -- considérez donc cette date comme l''objectif officiel actuel plutôt que comme une certitude définitive.', '["Contribuables assujettis : préparez des factures électroniques structurées et lisibles par machine (pas de PDF) prêtes à émettre avant l''échéance.", "Vérifiez que votre logiciel de facturation/point de vente/comptabilité peut produire le format de données structuré requis.", "Restez attentif aux prochaines directives du BIR -- l''échéance a déjà été repoussée une fois et la plateforme de transmission (ESRS) est encore en construction."]');
